import{z as p,x as n,o as E,c as l,q as t,j as i,D as a,d as o,s,S as d,b as B}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"管道与 IPC","description":"","frontmatter":{"title":"管道与 IPC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipc-pipe.md","filePath":"cs/ipc-pipe.md","lastUpdated":1791413859000}'),A={name:"cs/ipc-pipe.md"};function c(m,e,h,f,u,C){const r=n("Mermaid");return E(),l("div",null,[e[2]||(e[2]=t('<h1 id="管道与-ipc" tabindex="-1">管道与 IPC <a class="header-anchor" href="#管道与-ipc" aria-label="Permalink to &quot;管道与 IPC&quot;">​</a></h1><div class="epigraph"><p>管道是两个进程之间的字节流：一端写，一端读，内核做缓冲。</p><footer>—— 据 Ritchie and Thompson, The UNIX Time-Sharing System, 1974；Stevens, UNIX Network Programming 整理</footer></div><p><a href="/cs/sigmask">上一课</a>只能投递编号事件。<a href="/cs/process-image">进程映像</a>各有各的地址空间，用户指针不能直接递给别人。缺口是：两个进程要传<strong>字节</strong>，必须经过内核对象。本课以管道为原型，把共享内存与消息队列留作同一层的变体，不写成百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>父进程 fork 后想把标准输出接到子进程输入。若只靠信号，连一个字符都传不了。若把数据写进文件再读，延迟与命名都重。管道给出匿名字节流：内核环形缓冲，写满则写者阻塞，读空则读者阻塞，会合点正是<a href="/cs/syscall-path">系统调用</a>里的睡眠与<a href="/cs/interrupt-bottom-half">下半部</a>式的唤醒——这里唤醒者是另一端的 <code>read</code>/<code>write</code>，不是设备。</p><p>本课不把套接字当管道的特例讲完；套接字在网络课才出现，但会复用「文件描述符上的字节流」。</p><p><span class="marginnote">匿名管道只在亲缘进程间继承描述符。命名管道（FIFO）把同一对象挂进目录，让无亲缘进程也能打开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>pipe</code> 分配内核缓冲与两个描述符。写拷贝入核，读拷贝出核。关闭写端后读者收到文件结束；关闭读端后写者得信号 <code>SIGPIPE</code>。共享内存反过来：映射同一物理页，字节不经拷贝，但必须另做同步——同步是后面几课。消息队列按消息边界投递，仍是内核缓冲。</p>',9)),(E(),i(d,null,{default:a(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E8%BF%9B%E7%A8%8B%20write%22%5D%20--%3E%20BUF%5B%22%E5%86%85%E6%A0%B8%E7%AE%A1%E9%81%93%E7%BC%93%E5%86%B2%22%5D%0A%20%20BUF%20--%3E%20R%5B%22%E8%AF%BB%E8%BF%9B%E7%A8%8B%20read%22%5D%0A%20%20BUF%20--%3E%20BLK%5B%22%E6%BB%A1%E5%88%99%E5%86%99%E7%9D%A1%20%2F%20%E7%A9%BA%E5%88%99%E8%AF%BB%E7%9D%A1%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=B("h2",{id:"机制",tabindex:"-1"},[o("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=B("p",null,"IPC 把进程映像的隔离留住：页表仍分开，只有内核或双方同意的共享页能看见同一字节。管道强制流式、单向（标准匿名管道）；双向要两根或套接字。阻塞把调度指标重新请进来：写者睡时 CPU 可以给别人，这是管道与忙等轮询的差别。",-1)),(E(),i(d,null,{default:a(()=>[s(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98%3A%20%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E9%A1%B5%E6%98%A0%E5%B0%84%E8%BF%9B%E4%B8%A4%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20ZC%5B%22%E9%9B%B6%E6%8B%B7%E8%B4%9D%2C%20%E4%BD%86%E5%BF%85%E9%A1%BB%E8%87%AA%E5%B7%B1%E5%8A%A0%E9%94%81%22%5D%0A%20%20PIPE%5B%22%E7%AE%A1%E9%81%93%3A%20%E6%95%B0%E6%8D%AE%E6%8B%B7%E5%85%A5%E5%86%85%E6%A0%B8%E7%BC%93%E5%86%B2%E5%86%8D%E6%8B%B7%E5%87%BA%22%5D%20--%3E%20EASY%5B%22%E5%86%85%E6%A0%B8%E4%BB%A3%E7%AE%A1%E9%98%BB%E5%A1%9E%E4%B8%8E%E5%94%A4%E9%86%92%2C%20%E6%97%A0%E7%AB%9E%E6%80%81%E7%AA%97%E5%8F%A3%22%5D%0A%20%20MQ%5B%22%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%97%3A%20%E6%8C%89%E6%B6%88%E6%81%AF%E8%BE%B9%E7%95%8C%E6%8A%95%E9%80%92%22%5D%20--%3E%20MID%5B%22%E4%BB%8B%E4%BA%8E%E4%B8%A4%E8%80%85%3A%20%E4%BB%8D%E6%98%AF%E5%86%85%E6%A0%B8%E7%BC%93%E5%86%B2%2C%20%E4%BF%9D%E7%95%99%E8%BE%B9%E7%95%8C%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=t('<p><span class="marginnote">数字实例：Linux 管道缓冲默认 64 KB（<code>fcntl</code> 可查改到最大 1 MB）。生产者每秒写 128 KB、消费者每秒只读 64 KB 时，净积累 64 KB/s，64 KB 缓冲约一秒写满，写端随即阻塞——「背压」就是这条阻塞把速度差如实传给了上游。</span></p><p><span class="marginnote">常见误区：初学者容易以为 <code>ls | grep foo</code> 里 <code>ls</code> 的输出是直接「流进」<code>grep</code> 的内存。实际数据先 <code>write</code> 拷进内核的 64 KB 环形缓冲，<code>grep</code> 再 <code>read</code> 拷出来，共两次拷贝；要省这两次得用共享内存，并自己付同步的代价。</span></p><p>信号可以宣布「管道断了」，但仍不是负载。本课之后，默认「进程间有字节通道」；通道上的竞态要另说。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Mach port 的全部权利，不把 D-Bus 当内核原语。也不讲网络字节序：那是还没有对端主机。Unix 域套接字与管道相近，细节不背。</p><p>容量上限是内核参数。写端一次 <code>write</code> 在管道上不一定原子，只有小写在 POSIX 下有保证。</p><p>本课不把 <code>SOCK_SEQPACKET</code> 当管道的第三种。</p><p>后课默认：亲缘进程可用管道传字节。多执行流同时碰同一缓冲或同一共享页时会发生什么，留给后课的竞争与临界区；下一课把这条字节流挂进目录——命名管道。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管道是内核缓冲的字节流；满写睡、空读睡。</li><li>共享内存更省拷贝，但把互斥推给后课。</li><li>套接字是更后的跨机器通道，接口仍像文件。</li><li>出处：Ritchie and Thompson, <em>CACM</em> 1974；Stevens, <em>UNP</em>；Tanenbaum <em>MOS</em>。</li></ul>',10))])}const _=p(A,[["render",c]]);export{P as __pageData,_ as default};
